// Importações
import "../css/main.css";
import { Swiper, SwiperSlide } from "swiper/react";
import { Pagination } from "swiper/modules";
import "swiper/css";
import "swiper/css/pagination";

// Paleta de cores
const laranjinha1 = "#fe7e00";
const vermelhoescuro = "#a10000";
const vermelhoclaro = "#d41f00";
const ciano = "#009cb3";
const laranjinha2 = "#fe9053";
const amarelo = "#ffbb00";
const cinza_fundo = "#2e2e2e";
const cinza_contraste = "#f4f4f4";

// Componente Principal
export function Main() {
  return (
    <div className="mainpage_container">
        <Header />
        <Frontpage/>
        <Sinopsis/>
    </div>
  );
}

// Header com título
function Header() {
  return (
    <header className="mainpagetitle_container">
      <h1 className="mainpagetitle DynaPuff">Pandora</h1>
      <h2 className="mainpagesubtitle DynaPuff">Through the Forest!</h2>
    </header>
  );
}

// Carrossel de Imagens
function ImageCarousel() {
  return (
    <div className="mainpagecarosel_container">
      <Swiper
        modules={[Pagination]}
        className="mainpagecarosel"
        pagination={{ clickable: true }}
      >
        <SwiperSlide>
          <img
            className="mainpage"
            src={require("../imgs/menujoguinho.png")}
            alt="Imagem mostrando o menu do jogo, sua logo e interface (botões)"
          />
          <ParagonText
            font_s={30}
            text="Menu principal do Pandora!"
            outline
            aligntext="center"
            bg_color={cinza_fundo}
          />
        </SwiperSlide>

        <SwiperSlide>
          <ParagonText
            font_s={24}
            text="Explore a floresta e enfrente os desafios!"
            aligntext="center"
            bg_color={cinza_fundo}
            outline
          />
        </SwiperSlide>
      </Swiper>
    </div>
  );
}


function Frontpage()
{
    return(      
    <section className="mainpage_frontpage">
        <ImageCarousel />
        <ParagonText
          aligntext="right"
          font_s={16}
          containerheight="450px"
          text_color={cinza_contraste}
          text={`O jogo Pandora é feito na Unity 6 para satisfazer as competências e requisitos do Projeto Integrador (PI)
          do curso técnico em programação de jogos contemplado e realizado no
          Senac Papaléo.`}
        />
      </section>
    )
}

function Sinopsis()
{ 
    return(
    <section className="mainpage_sinopsis_container">
        <ParagonText
          title="Sinopse"
          title_color={cinza_contraste}
          aligntext="center"
          font_s={15}
          containerheight="300px"
          text_color={cinza_contraste}
          text="Em um mundo misterioso e repleto de perigos, Pandora precisa atravessar uma floresta mágica para cumprir seu destino. Enfrente inimigos, colete artefatos e descubra segredos escondidos nas sombras."
        />
      </section>
    );
}


// Texto estilizado reutilizável
function ParagonText({
  text = "Placeholder",
  title = "",
  outline = false,
  text_color = cinza_fundo,
  bg_color = cinza_fundo,
  font_s = 20,
  containerheight = "fit-content",
  aligntext = "center",
  aligntitle = "left",
  title_color = cinza_fundo,
}) {
  const outlineClass = outline ? "outline" : "";
  const baseClass = `mainpage DynaPuff ${outlineClass}`;

  const containerStyle = {
    height: containerheight,
  };

  const innerContainerStyle = {
    backgroundColor: bg_color,
    height: containerheight,
  };

  const titleStyle = {
    margin: 0,
    color: title_color,
    textAlign: aligntitle
  };

  const textStyle = {
    color: text_color,
    fontSize: font_s,
    textAlign: aligntext,
  };

  return (
    <div className="p_container_outer" style={containerStyle}>
      <div className="p_container" style={innerContainerStyle}>
        {title && <h1 className={baseClass} style={titleStyle}>{title}</h1>}
        <p className={baseClass} style={textStyle}>{text}</p>
      </div>
    </div>
  );
}
